pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        (uint256 storedBlock, bytes32 storedGuess) = getGuess(actor);
        assertTrue(storedBlock != 0);
    }

    function getGuess(address actor) internal returns (uint256, bytes32) {
        bytes32 key = keccak256(abi.encodePacked(actor, uint256(0)));

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.roll(block.number + 3);
        vm.prank(actor);
        try c.settle() {
            return (1, bytes32(0));
        } catch {
            return (0, bytes32(0));
        }
    }
}
